events=[]
class Flag:
    def __bool__(self):
        events.append('bool')
        return enabled
class Text(str):
    def __str__(self): raise AssertionError('str')
    def __len__(self): raise AssertionError('len')
    def __iter__(self): raise AssertionError('iter')
class Data(bytes):
    def __bytes__(self): raise AssertionError('bytes')
    def __len__(self): raise AssertionError('len')
    def __iter__(self): raise AssertionError('iter')
for enabled in (False,True):
    events.clear()
    assert a2b_base64(Text('QQ=='),strict_mode=Flag()) == b'A'
    assert a2b_base64(Data(b'QQ=='),strict_mode=Flag()) == b'A'
    assert b2a_base64(Data(b'A'),newline=Flag()) == (b'QQ==\n' if enabled else b'QQ==')
    assert events == ['bool','bool','bool']

events=[]
failure=ValueError('truth failure')
class Flag:
    def __bool__(self):
        events.append('bool')
        raise failure
for fn,option,data in ((a2b_base64,'strict_mode',b'QQ=='),(b2a_base64,'newline',b'A')):
    events.clear()
    try: fn(data,**{option:Flag()})
    except ValueError as error: assert error is failure
    else: assert False
    assert events == ['bool']
for data in ('é','\ud800'):
    events.clear()
    try: a2b_base64(data,strict_mode=Flag())
    except ValueError as error: assert error.args == ('string argument should contain only ASCII characters',)
    else: assert False
    assert events == []

events=[]
class Flag:
    def __len__(self):
        events.append('len')
        return 0
assert b2a_base64(b'A',newline=Flag()) == b'QQ=='
assert a2b_base64(b'!QQ==',strict_mode=Flag()) == b'A'
assert events == ['len','len']
class Bad:
    def __bool__(self): return 1
for fn,option in ((a2b_base64,'strict_mode'),(b2a_base64,'newline')):
    try: fn(b'',**{option:Bad()})
    except TypeError as error: assert error.args == ('__bool__ should return bool, returned int',)
    else: assert False

events=[]
class Key(str):
    def __hash__(self): return str.__hash__(self)
    def __eq__(self,other):
        events.append(other)
        return str.__eq__(self,other)
    def __str__(self):
        events.append('str')
        return 'rendered'
for fn,option in ((a2b_base64,'strict_mode'),(b2a_base64,'newline')):
    events.clear()
    assert fn(b'',**{Key(option):False}) == b''
    assert events == []
    try: fn(b'',**{Key('wrong'):False})
    except TypeError as error: assert error.args == (fn.__name__+"() got an unexpected keyword argument 'rendered'",)
    else: assert False
    assert events == [option,'str']

